import{_ as n,C as t,o as s,c as d,E as e,a6 as l}from"./chunks/framework.QBF2cGGQ.js";const m=JSON.parse('{"title":"学习中心","description":"","frontmatter":{"layout":"doc","pageClass":"learn-page","title":"学习中心","aside":false},"headers":[],"relativePath":"learn/index.md","filePath":"learn/index.md","lastUpdated":null}'),p={name:"learn/index.md"};function c(i,o,u,_,g,h){const a=t("LearnHero"),r=t("LearnDashboard");return s(),d("div",null,[e(a),e(r),o[0]||(o[0]=l('<h2 id="这个平台怎么用" tabindex="-1">这个平台怎么用 <a class="header-anchor" href="#这个平台怎么用" aria-label="Permalink to &quot;这个平台怎么用&quot;">​</a></h2><p><strong>1. 按步骤读，不要一次看完。</strong> 每一步结束都有一个&quot;停一下，先回答&quot;的问题。想 30 秒再看下一段，效果比连读三遍好。想不出来是正常的，那正是你该学的地方。</p><p><strong>2. 练习不要靠猜。</strong> 每道题都有三级提示：第一层给思路，第二层给关键线索，第三层才给完整讲解。<strong>直接看第三层等于没做。</strong> 判分后会告诉你为什么对、为什么错、对应哪个知识点。</p><p><strong>3. 编程题是真的在跑。</strong> 代码在独立沙箱 iframe 里执行（拿不到本页面 DOM、cookie、localStorage），通过检查项才算过。Node.js 的 <code>http</code>/<code>fs</code> 这类跑不了，那部分给的是&quot;本地运行说明 + 代码审查&quot;，<strong>不会假装它跑起来了</strong>。</p><p><strong>4. 测试是硬门槛。</strong> 全部练习通过才能解锁掌握测试，测试通过才标记&quot;已掌握&quot;。这不是为了卡你，是因为&quot;我读完了&quot;和&quot;我会了&quot;是两件事，只有测试能区分。</p><p><strong>5. 错了会自动进错题本。</strong> 按 1 → 3 → 7 → 21 天排期复习，做对一次推进一轮，四轮算消化。</p><h2 id="关于-ai-导师" tabindex="-1">关于 AI 导师 <a class="header-anchor" href="#关于-ai-导师" aria-label="Permalink to &quot;关于 AI 导师&quot;">​</a></h2><p>页面底部的&quot;AI 导师&quot;需要你自己跑一个本地代理服务（<code>node server/tutor.mjs</code>），Key 只存在服务端环境变量里。<strong>没配置时会明确显示&quot;未配置&quot;，不会编造回答。</strong> 不配置完全不影响学习——正文、练习、判分、进度都不依赖它。</p><h2 id="现在有什么" tabindex="-1">现在有什么 <a class="header-anchor" href="#现在有什么" aria-label="Permalink to &quot;现在有什么&quot;">​</a></h2><p>目前只有第一课是完整的交互课程。其余 23 个模块指向已有的知识地图章节（27 章 / 1256 个知识点），那是<strong>参考资料，不是课程</strong>。</p><p>我没有用空壳课程把 24 个模块填满——那样看起来完整，实际上是骗人的。后续课程会按同一标准逐节补，每补一节就在这里多一个入口。</p>',11))])}const f=n(p,[["render",c]]);export{m as __pageData,f as default};
